 function say(text){ui.notice.textContent=text;ui.notice.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.notice.classList.remove('show'),1900)}
 function audio(){if(muted)return;try{if(!sounds)sounds=new(window.AudioContext||window.webkitAudioContext)();if(sounds.state==='suspended')sounds.resume();const o=sounds.createOscillator(),g=sounds.createGain();o.connect(g);g.connect(sounds.destination);o.type='triangle';o.frequency.value=540;g.gain.setValueAtTime(.035,sounds.currentTime);g.gain.exponentialRampToValueAtTime(.001,sounds.currentTime+.12);o.start();o.stop(sounds.currentTime+.13)}catch(e){}}
 function poly(points,fill,stroke='#171922',lw=2){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
 function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
-function glow(x,y,r,color,alpha=1){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color.replace(')',`,${alpha})`).replace('rgb','rgba'));g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
+function glow(x,y,r,color,alpha=1){const g=ctx.createRadialGradient(x,y,0,x,y,r);let stop=color.startsWith('#')?rgba(color,alpha):color.replace(/rgba?\(([^)]+)\)/,(_,v)=>{const a=v.split(',').map(Number);return`rgba(${a[0]},${a[1]},${a[2]},${(a[3]??1)*alpha})`});g.addColorStop(0,stop);g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
 function rgba(hex,a){let v=hex.replace('#','');if(v.length===3)v=v.split('').map(x=>x+x).join('');return`rgba(${parseInt(v.slice(0,2),16)},${parseInt(v.slice(2,4),16)},${parseInt(v.slice(4,6),16)},${a})`}
 function line(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
 function drawBg(t){ctx.fillStyle='#111923';ctx.fillRect(0,0,W,H);let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1b2430');g.addColorStop(.55,'#25272c');g.addColorStop(1,'#302623');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // distant ridge layers

