node --input-type=module <<'JS'
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox','--disable-dev-shm-usage']});
const page = await browser.newPage({viewport:{width:1440,height:900}});
const errors=[]; page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3002/index.html');
await page.locator('#begin').click();
const box=await page.locator('#world').boundingBox();
await page.locator('#world').click({position:{x:box.width*.5,y:box.height*(329/650)}});
await page.waitForTimeout(100);
const built=await page.locator('#gold').textContent();
await page.locator('#waveBtn').click();
await page.waitForTimeout(3000);
const status=await page.locator('#waveState').textContent();
console.log(JSON.stringify({builtGold:built,waveStatus:status,pageErrors:errors}));
await browser.close();
if(built!=='7'||!status.includes('UNDER SIEGE')||errors.length) process.exit(1);
